#include <stdio.h>


int main(void)
{
    int leaves = 1;
    for (int depth = 0; depth < 3; depth++) {
        leaves *= 2;
    }
    printf("%d\n", leaves);
    return 0;
}

#include <stdio.h>


int main(void)
{
    int a[3] = {2, 3, 5}, sum = 0;
    for (int i = 0; i < 3; i++) {
        if (5u & (1u << i)) {
            sum += a[i];
        }
    }
    printf("%d\n", sum);
    return 0;
}

