#include <stdio.h>


int main(void)
{
    int a = 48, b = 18;
    while (b) {
        int r = a % b;
        a = b; b = r;
    }
    printf("%d\n", a);
    return 0;
}

#include <stdio.h>


int main(void)
{
    int pairs = 0;
    for (int i = 0; i < 4; i++) {
        for (int j = i + 1; j < 4; j++) {
            pairs++;
        }
    }
    printf("%d\n", pairs);
    return 0;
}
